def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Indexed history
    me = [h[0] for h in history]
    op = [h[1] for h in history]

    # Score differential and opponent stats
    my_score = 0
    op_score = 0
    opp_c = 0
    for i in range(n):
        a = me[i]
        b = op[i]
        if b == 'C':
            opp_c += 1
        if a == 'C' and b == 'C':
            my_score += 3
            op_score += 3
        elif a == 'C' and b == 'D':
            op_score += 5
        elif a == 'D' and b == 'C':
            my_score += 5
        else:
            my_score += 1
            op_score += 1

    last_my = me[-1]
    last_op = op[-1]
    coop_rate = opp_c / n
    remaining = 100 - n

    # Detect always-cooperate / always-defect quickly
    if opp_c == n:
        # Opponent never defected. Take final-round advantage; otherwise cooperate.
        if remaining <= 1:
            return 'D'
        return 'C'
    if opp_c == 0:
        return 'D'

    # Detect mirroring of our lagged action (opponent follows our previous move)
    # This is the classic opponent of Tit-for-Tat: they play what we played last round.
    mirror_hits = 0
    mirror_tot = 0
    for i in range(1, n):
        if op[i] == me[i - 1]:
            mirror_hits += 1
        mirror_tot += 1
    mirror_score = mirror_hits / mirror_tot if mirror_tot else 0.0

    # Detect opponent's last action pattern: runs
    consec_op_d = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'D':
            consec_op_d += 1
        else:
            break
    consec_op_c = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'C':
            consec_op_c += 1
        else:
            break

    # Recent window stats (last 12)
    w = 12
    start = n - w if n > w else 0
    recent_op_d = 0
    recent_op_c = 0
    recent_my_d = 0
    for i in range(start, n):
        if op[i] == 'D':
            recent_op_d += 1
        else:
            recent_op_c += 1
        if me[i] == 'D':
            recent_my_d += 1
    window_len = n - start
    recent_op_def_rate = recent_op_d / window_len

    # === Late game: 100-round horizon, exploit at the end ===
    if remaining <= 4:
        # If opponent is likely to cooperate, defect for 5 vs 3.
        # If opponent is likely to defect, defect to avoid 0.
        if coop_rate > 0.35 or recent_op_def_rate < 0.6:
            return 'D'
        return 'D'

    # === Opening: cooperate to build trust ===
    if n <= 2:
        return 'C'

    # === Against strong mirrorers: cooperate to keep the C-C engine running ===
    if mirror_score > 0.75 and n >= 5 and coop_rate > 0.5:
        # Only defect in the final rounds
        if remaining <= 2:
            return 'D'
        return 'C'

    # === Against mostly cooperative opponents: cooperate, with occasional probing ===
    if coop_rate >= 0.85 and recent_op_def_rate <= 0.2:
        # Avoid probing against a pure cooperator until the very end
        # Rare single probe to gather info in mid-game
        if n > 20 and remaining > 20 and n % 23 == 0 and rng.random() < 0.15:
            return 'D'
        return 'C'

    # === Against exploiters (very high recent defection) ===
    if recent_op_def_rate >= 0.7:
        # Defect hard, with rare forgiveness probe to escape DD lock-in
        if consec_op_d >= 4:
            # Try one C to reset if we've been stuck in DD
            if consec_op_c == 0 and rng.random() < 0.12:
                return 'C'
            return 'D'
        if recent_op_d >= 9:
            return 'D'
        if last_op == 'D':
            if rng.random() < 0.08:
                return 'C'
            return 'D'
        # Last op C: reward occasionally, exploit mostly
        if coop_rate < 0.4:
            if rng.random() < 0.5:
                return 'D'
        return 'C'

    # === General interaction: score-aware, reciprocal, anti-lock-in ===

    # If we're already stuck in mutual defection, try to break out
    if last_my == 'D' and last_op == 'D':
        # DD gives 1 each. Try C sometimes to test if opponent will reciprocate.
        if consec_op_d >= 2:
            # Check if opponent ever cooperates after our C in recent history
            responded_c = False
            for i in range(start, n - 1):
                if me[i] == 'C' and op[i + 1] == 'C':
                    responded_c = True
                    break
            if responded_c:
                return 'C'
            if rng.random() < 0.25:
                return 'C'
            return 'D'
        return 'D'

    # Opponent just defected, we cooperated -> exploited.
    # Strong reciprocity: retaliate, but don't get trapped.
    if last_op == 'D' and last_my == 'C':
        # If opponent normally cooperates (noise / rare D), forgive quickly
        if coop_rate >= 0.7 and recent_op_def_rate <= 0.25:
            if rng.random() < 0.75:
                return 'C'
            return 'D'
        # Opponent has a notable defection pattern: retaliate
        if consec_op_d >= 3:
            return 'D'
        if rng.random() < 0.75:
            return 'D'
        return 'C'

    # Opponent just cooperated, we defected -> we exploited.
    # Return to cooperation to sustain mutual gains, but only if the opponent is reliable.
    if last_op == 'C' and last_my == 'D':
        if coop_rate >= 0.5:
            return 'C'
        # Opponent cooperation might be opportunistic; probe once more
        if recent_op_def_rate >= 0.4 and rng.random() < 0.4:
            return 'D'
        return 'C'

    # Both cooperating (main line).
    # Stay in C-C, but probe occasionally when opponent seems a bit exploitable.
    if coop_rate >= 0.6:
        # Scoring is close enough; keep cooperating with rare probes.
        if remaining > 8 and n > 12 and n % 19 == 0 and rng.random() < 0.1:
            # Only probe if opponent looks somewhat forgiving
            if recent_op_def_rate < 0.35:
                return 'D'
        # If we're far behind, be more aggressive
        if n >= 25 and my_score < op_score - 15:
            if rng.random() < 0.4:
                return 'D'
        return 'C'

    # Opponent mixed (coop_rate < 0.6) but last was C: cautiously cooperate.
    if n >= 20 and my_score < op_score - 20:
        # We're being exploited overall; push D more
        if rng.random() < 0.5:
            return 'D'
    return 'C'
